"""Tests for parse_amount function."""
import math

from amount import parse_amount


def test_parse_amount_basic():
    """Test basic parsing."""
    assert parse_amount("100") == 100.0
    assert parse_amount("10.5") == 10.5
    assert parse_amount("1,5") == 10.5


def test_parse_amount_spaces():
    """Test spaces around input."""
    assert parse_amount(" 100 ") == 100.0
    assert parse_amount(" 10.5 ") == 10.5
    assert parse_amount(" 1,5 ") == 10.5


def test_parse_amount_zero():
    """Test zero values."""
    assert parse_amount("0") == 0.0
    assert parse_amount("0.0") == 0.0
    assert parse_amount("0,0") == 0.0


def test_parse_amount_negative_rejected():
    """Test that negative values raise ValueError."""
    try:
        parse_amount("-100")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_parse_amount_empty_rejected():
    """Test that empty strings raise ValueError."""
    try:
        parse_amount("")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


def test_parse_amount_whitespace_only_rejected():
    """Test that whitespace-only strings raise ValueError."""
    try:
        parse_amount("   ")
        assert False, "Should have raised ValueError"
    except ValueError:
        pass


